use std::{num::NonZero, sync::LazyLock};

use lb_blend_proofs::{quota::VerifiedProofOfQuota, selection::VerifiedProofOfSelection};
use lb_cryptarchia_engine::Epoch;
use lb_groth16::Fr;
use lb_key_management_system_keys::keys::{Ed25519Key, ZkPublicKey};

use crate::{
    mantle::{
        channel::{SlotTimeframe, SlotTimeout},
        fixtures::programs::sample_key,
        notes::{NoteCommitment, NoteNullifier},
        ops::{
            channel::{
                ChannelId, MsgId,
                config::ChannelConfigOp,
                deposit::{DepositOp, Metadata},
                inscribe::{ChannelStep, InscriptionOp, MiniBlock, Step},
                program_step::{Payment, ProgramOutputs, ProgramStep},
                withdraw::ChannelWithdrawOp,
            },
            pow::ClaimPowRewardOp,
            program::ProgramRegisterOp,
            sdp::{SDPActiveOp, SDPDeclareOp, SDPWithdrawOp},
            transfer::TransferOp,
        },
    },
    sdp::{
        ActivityMetadata, DeclarationId, Locator, Nonce, ProviderId, ServiceType,
        blend::ActivityProof,
    },
};

pub static TRANSFER: LazyLock<TransferOp> = LazyLock::new(|| TransferOp {
    inputs: [
        NoteNullifier(Fr::from(0x01u64)),
        NoteNullifier(Fr::from(0x02u64)),
    ]
    .into(),
    outputs: [
        NoteCommitment(Fr::from(0x03u64)),
        NoteCommitment(Fr::from(0x04u64)),
    ]
    .into(),
    commitment_merkle_root: Fr::from(0x05u64),
    excess_value: 0x06,
});

pub static PROGRAM_REGISTER: LazyLock<ProgramRegisterOp> = LazyLock::new(|| ProgramRegisterOp {
    verification_key: sample_key(),
});

pub static CHANNEL_CONFIG: LazyLock<ChannelConfigOp> = LazyLock::new(|| {
    ChannelConfigOp::new(
        ChannelId::from([0x10u8; 32]),
        MsgId::root(),
        [
            Ed25519Key::from_bytes(&[0x11u8; 32]).public_key(),
            Ed25519Key::from_bytes(&[0x12u8; 32]).public_key(),
        ]
        .into(),
        SlotTimeframe::from(0x13u32),
        SlotTimeout::from(0x14u32),
        NonZero::new(0x02).unwrap(),
    )
    .unwrap()
});

pub static INSCRIPTION: LazyLock<InscriptionOp> = LazyLock::new(|| InscriptionOp {
    channel_id: ChannelId::from([14u8; 32]),
    inscription: b"hello logos".into(),
    parent: MsgId::root(),
    signer: Ed25519Key::from_bytes(&[15u8; 32])
        .public_key()
        .into_unverified(),
    mini_blocks: [MiniBlock::from([
        Step::User(ChannelStep {
            inputs: [NoteNullifier(Fr::from(0x23u64))].into(),
            outputs: [NoteCommitment(Fr::from(0x24u64))].into(),
            commitment_merkle_root: Fr::from(0x25u64),
        }),
        Step::Program(ProgramStep {
            program_id: Fr::from(0x34u64),
            payments: [Payment {
                inputs: [NoteNullifier(Fr::from(0x35u64))].into(),
                outputs: [NoteCommitment(Fr::from(0x36u64))].into(),
                commitment_merkle_root: Fr::from(0x37u64),
                paid_value: 0x38,
                intent: Fr::from(0x39u64),
            }]
            .into(),
            inputs: [NoteNullifier(Fr::from(0x3au64))].into(),
            outputs: [NoteCommitment(Fr::from(0x3bu64))].into(),
            program_outputs: ProgramOutputs::from(0b1),
            commitment_merkle_root: Fr::from(0x3cu64),
            spend_notes_hash: Fr::from(0x3du64),
        }),
    ])]
    .into(),
});

pub static DEPOSIT: LazyLock<DepositOp> = LazyLock::new(|| DepositOp {
    channel_id: ChannelId::from([16u8; 32]),
    inputs: [NoteNullifier(Fr::from(0x11u64))].into(),
    commitment_merkle_root: Fr::from(0x26u64),
    outputs: [NoteCommitment(Fr::from(0x27u64))].into(),
    excess_value: 0x28,
    metadata: Metadata::try_from(b"deposit-metadata".to_vec())
        .expect("the metadata is within bounds"),
});

pub static CHANNEL_WITHDRAW: LazyLock<ChannelWithdrawOp> = LazyLock::new(|| ChannelWithdrawOp {
    channel_id: ChannelId::from([18u8; 32]),
    inputs: [NoteNullifier(Fr::from(0x13u64))].into(),
    commitment_merkle_root: Fr::from(0x29u64),
    outputs: [NoteCommitment(Fr::from(0x2au64))].into(),
});

pub static SDP_DECLARE: LazyLock<SDPDeclareOp> = LazyLock::new(|| SDPDeclareOp {
    service_type: ServiceType::BlendNetwork,
    locators: [Locator::new_unchecked(
        "/ip4/127.0.0.1/udp/3000/quic-v1".parse().unwrap(),
    )]
    .try_into()
    .unwrap(),
    provider_id: ProviderId(Ed25519Key::from_bytes(&[24u8; 32]).public_key()),
    zk_id: ZkPublicKey::from(Fr::from(25u64)),
    note_pk: ZkPublicKey::from(Fr::from(48u64)),
    inputs: [NoteNullifier(Fr::from(26u64))].into(),
    commitment_merkle_root: Fr::from(44u64),
    amount: 45,
});

pub static SDP_WITHDRAW: LazyLock<SDPWithdrawOp> = LazyLock::new(|| SDPWithdrawOp {
    declaration_id: DeclarationId([27u8; 32]),
    nonce: Nonce::new(Epoch::new(0), 29),
    service_note_nullifier: NoteNullifier(Fr::from(28u64)),
    outputs: [NoteCommitment(Fr::from(46u64))].into(),
    excess_value: 47,
});

pub static SDP_ACTIVE: LazyLock<SDPActiveOp> = LazyLock::new(|| SDPActiveOp {
    declaration_id: DeclarationId([0x80u8; 32]),
    nonce: Nonce::new(Epoch::new(0), 0x81),
    metadata: ActivityMetadata::Blend(Box::new(ActivityProof {
        epoch: Epoch::new(0x82),
        signing_key: Ed25519Key::from_bytes(&[0x83u8; 32]).public_key(),
        proof_of_quota: VerifiedProofOfQuota::from_bytes_unchecked([0x84u8; _]).into(),
        proof_of_selection: VerifiedProofOfSelection::from_bytes_unchecked([0x85u8; _]).into(),
    })),
});

pub static CLAIM_POW_REWARD: LazyLock<ClaimPowRewardOp> = LazyLock::new(|| ClaimPowRewardOp {
    epoch_nonce: Fr::from(0x30u64),
    block_hash: [0x31u8; 32],
    public_key: ZkPublicKey::new(Fr::from(0x32u64)),
    nonce: Fr::from(0x33u64),
});

